"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[5670],{589(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/AndroidCameraParameters/de/","label":"App-\xdcbersicht","docId":"overview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/development","label":"Entwicklerdokumentation","docId":"development","unlisted":false},{"type":"category","label":"Mastering Android Camera2 API","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/AndroidCameraParameters/de/camera2/welcome-to-android-camera2","label":"Kapitel 1: Willkommen bei Android Camera2","docId":"camera2/welcome-to-android-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/understanding-smartphone-cameras","label":"Kapitel 2: Smartphone-Kameras verstehen","docId":"camera2/understanding-smartphone-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/what-can-modern-smartphone-cameras-do","label":"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen","docId":"camera2/what-can-modern-smartphone-cameras-do","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/exploring-your-phones-camera","label":"Kapitel 4: Das eigene Telefon erkunden","docId":"camera2/exploring-your-phones-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/creating-your-first-camera2-project","label":"Kapitel 5: Erstellen Ihres ersten Camera2-Projekts","docId":"camera2/creating-your-first-camera2-project","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/discovering-cameras","label":"Kapitel 6: Kameras entdecken","docId":"camera2/discovering-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/opening-a-camera","label":"Kapitel 7: Eine Kamera \xf6ffnen","docId":"camera2/opening-a-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/showing-camera-preview","label":"Kapitel 8: Die Kameravorschau anzeigen","docId":"camera2/showing-camera-preview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/taking-photos","label":"Kapitel 9: Fotos aufnehmen","docId":"camera2/taking-photos","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/the-camera2-pipeline","label":"Kapitel 10: Die Camera2-Pipeline","docId":"camera2/the-camera2-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/capture-types","label":"Kapitel 11: Aufnahme-Typen","docId":"camera2/capture-types","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/cameracharacteristics-deep-dive","label":"Kapitel 12: Tiefer Einblick in CameraCharacteristics","docId":"camera2/cameracharacteristics-deep-dive","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/exposure","label":"Kapitel 13: Belichtung","docId":"camera2/exposure","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/manual-exposure-in-camera2","label":"Kapitel 14: Manuelle Belichtung in Camera2","docId":"camera2/manual-exposure-in-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/focus","label":"Kapitel 15: Fokus","docId":"camera2/focus","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/white-balance-and-color","label":"Kapitel 16: Wei\xdfabgleich & Farbe","docId":"camera2/white-balance-and-color","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/3a-pipeline","label":"Kapitel 17: Die 3A-Pipeline","docId":"camera2/3a-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/raw-photography","label":"Kapitel 18: RAW-Fotografie","docId":"camera2/raw-photography","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/high-speed-video","label":"Kapitel 19: High-Speed-Video","docId":"camera2/high-speed-video","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/multi-camera","label":"Kapitel 20: Multi-Kamera","docId":"camera2/multi-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/hdr-and-ultra-hdr","label":"Kapitel 21: HDR & Ultra HDR","docId":"camera2/hdr-and-ultra-hdr","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/camera-extensions","label":"Kapitel 22: Kamera-Erweiterungen","docId":"camera2/camera-extensions","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/zero-shutter-lag-and-reprocessing","label":"Kapitel 23: Zero Shutter Lag & Reprocessing","docId":"camera2/zero-shutter-lag-and-reprocessing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/camerax","label":"Kapitel 24: CameraX","docId":"camera2/camerax","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/native-camera-development","label":"Kapitel 25: Native Kameraentwicklung","docId":"camera2/native-camera-development","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/asynchronous-camera-programming","label":"Kapitel 26: Asynchrone Kameraprogrammierung","docId":"camera2/asynchronous-camera-programming","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/camera-testing","label":"Kapitel 27: Kameratests","docId":"camera2/camera-testing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/camera2-architecture","label":"Kapitel 28: Camera2-Architektur","docId":"camera2/camera2-architecture","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/de/camera2/camera-metadata-encyclopedia","label":"Camera Metadata Encyclopedia","docId":"camera2/camera-metadata-encyclopedia","unlisted":false}],"href":"/AndroidCameraParameters/de/category/mastering-android-camera2-api"},{"type":"link","href":"/AndroidCameraParameters/de/data-safety","label":"Datensicherheitshandbuch","docId":"data-safety","unlisted":false}]},"docs":{"camera2/3a-pipeline":{"id":"camera2/3a-pipeline","title":"Kapitel 17: Die 3A-Pipeline","description":"Orchestrieren Sie Auto Exposure (AE), Auto Focus (AF) und Auto White Balance (AWB) zu einer zuverl\xe4ssigen Aufnahmesequenz f\xfcr die Standbildfotografie. Lernen Sie den Precapture-Trigger, Blitzmodi sowie die AE/AF-Zustandsmaschinen kennen und erstellen Sie produktionsreifen Kotlin-Code, der alle drei A\'s vor jeder Aufnahme koordiniert.","sidebar":"tutorialSidebar"},"camera2/asynchronous-camera-programming":{"id":"camera2/asynchronous-camera-programming","title":"Kapitel 26: Asynchrone Kameraprogrammierung","description":"B\xe4ndigen Sie die Callback-H\xf6lle von Camera2 mit Kotlin Coroutines und Flow. Lernen Sie suspendCancellableCoroutine f\xfcr One-Shot-Operationen (openCamera, createCaptureSession, capture), callbackFlow f\xfcr kontinuierliche ImageReader- und CaptureResult-Streams, Combine-Operatoren f\xfcr reaktive UIs und Muster zur Thread-Sicherheit kennen, um ANRs und Deadlocks zu verhindern.","sidebar":"tutorialSidebar"},"camera2/camera-extensions":{"id":"camera2/camera-extensions","title":"Kapitel 22: Kamera-Erweiterungen","description":"Verwenden Sie die CameraExtensionSession f\xfcr OEM-beschleunigte computergest\xfctzte Fotografie: Nachtmodus, Bokeh-Portr\xe4tmodus, HDR-Erweiterung, Gesichtsretusche und Automatikmodus. Fragen Sie die CameraExtensionCharacteristics ab, verwalten Sie die Latenz und vergleichen Sie die Architektur von Standard- vs. Extension-Sitzungen.","sidebar":"tutorialSidebar"},"camera2/camera-metadata-encyclopedia":{"id":"camera2/camera-metadata-encyclopedia","title":"Camera Metadata Encyclopedia","description":"Complete reference guide for all essential CameraCharacteristics metadata keys including Sensor, Lens, Control, Scaler, Request, Flash, JPEG, Statistics, and Info categories.","sidebar":"tutorialSidebar"},"camera2/camera-testing":{"id":"camera2/camera-testing","title":"Kapitel 27: Kameratests","description":"Der umfassende Leitfaden f\xfcr Android-Kameratests. Verstehen Sie Camera ITS (Image Test Suite), was OEMs vor der Auslieferung validieren (Funktionskombinationen, Szenentests, Sensor-Fusion), manuelle CTS-Verifier-Tests und wie Sie Ihre eigenen Instrumentierungstests mit Mockito-Mocks und parametrisierten Hardware-Level-Tests schreiben, die in der CI laufen.","sidebar":"tutorialSidebar"},"camera2/camera2-architecture":{"id":"camera2/camera2-architecture","title":"Kapitel 28: Camera2-Architektur","description":"Das gro\xdfe Architektur-Finale von Camera2. Reisen Sie durch den gesamten Stack, von Ihrer Kotlin-App \xfcber Binder-IPC, das Framework, den CameraService in Native, Camera3Device, HAL3 mit camera3_device_t, den V4L2-Kerneltreiber bis hin zum physischen Sensor, ISP, VCM-Objektiv und der Blitz-Hardware. Enth\xe4lt die Treble-HAL-Anforderung, den LEGACY HAL1-Wrapper und Android 15\'s CameraDeviceSetup. Komplette Map der Schichten f\xfcr die Reise des Lesers.","sidebar":"tutorialSidebar"},"camera2/cameracharacteristics-deep-dive":{"id":"camera2/cameracharacteristics-deep-dive","title":"Kapitel 12: Tiefer Einblick in CameraCharacteristics","description":"Meistern Sie CameraCharacteristics \u2014 die unver\xe4nderlichen statischen Metadaten, die jede Kamera beschreiben, bevor Sie sie \xf6ffnen. Hardware-Level (LEGACY, LIMITED, FULL, LEVEL_3, EXTERNAL), Capability-Flags, Organisation der Metadaten-Schl\xfcssel und Laufzeit-F\xe4higkeitsabfragen.","sidebar":"tutorialSidebar"},"camera2/camerax":{"id":"camera2/camerax","title":"Kapitel 24: CameraX","description":"Meistern Sie CameraX, die Lifecycle-bewusste Kamera-Bibliothek von Jetpack, die Camera2 kapselt. Lernen Sie die UseCase-Architektur, Camera2Interop zum Einschleusen manueller Parameter und ein Entscheidungs-Framework f\xfcr die Wahl zwischen CameraX und Camera2 kennen.","sidebar":"tutorialSidebar"},"camera2/capture-types":{"id":"camera2/capture-types","title":"Kapitel 11: Aufnahme-Typen","description":"Lernen Sie die drei Camera2-Aufnahme-Typen kennen \u2013 One-Shot (capture), Burst (captureBurst) und Repeating (setRepeatingRequest) \u2013 sowie die integrierten Vorlagen (TEMPLATE_PREVIEW, TEMPLATE_STILL_CAPTURE, TEMPLATE_RECORD und weitere).","sidebar":"tutorialSidebar"},"camera2/creating-your-first-camera2-project":{"id":"camera2/creating-your-first-camera2-project","title":"Kapitel 5: Erstellen Ihres ersten Camera2-Projekts","description":"Richten Sie ein komplettes Android Camera2-Projekt von Grund auf neu ein. Erfahren Sie mehr \xfcber Kameraberechtigungen, die Initialisierung des CameraManager, Hintergrund-Threading mit HandlerThread und die f\xfcr die TextureView-Hardwarebeschleunigung erforderliche Projektkonfiguration.","sidebar":"tutorialSidebar"},"camera2/discovering-cameras":{"id":"camera2/discovering-cameras","title":"Kapitel 6: Kameras entdecken","description":"Z\xe4hlen Sie jede Kamera auf einem Android-Ger\xe4t auf und fragen Sie sie mit CameraCharacteristics ab. Lernen Sie die Semantik von Kamera-IDs, die Ausrichtung von Objektiven (Vorderseite/R\xfcckseite/extern), externe USB-OTG-Kameras und die Hierarchie der Hardware-Level von LEGACY bis LEVEL_3 kennen.","sidebar":"tutorialSidebar"},"camera2/exploring-your-phones-camera":{"id":"camera2/exploring-your-phones-camera","title":"Kapitel 4: Das eigene Telefon erkunden","description":"Verwenden Sie die Begleit-App Android Camera Parameters, um Ihr eigenes Ger\xe4t zu inspizieren. Lernen Sie, Kamera-IDs zu lesen, Hardware-Levels zu pr\xfcfen, Kameras aufzuz\xe4hlen, unterst\xfctzte Formate, Bildraten, Zoombereiche und die RAW-F\xe4higkeit zu inspizieren.","sidebar":"tutorialSidebar"},"camera2/exposure":{"id":"camera2/exposure","title":"Kapitel 13: Belichtung","description":"Meistern Sie die Grundlagen der fotografischen Belichtung \u2013 das Belichtungsdreieck aus ISO, Verschlusszeit und Blende. Verstehen Sie EV-Stufen, die Sunny-16-Regel und wie verschiedene Kombinationen dieselbe Belichtung mit kreativen Kompromissen erzeugen.","sidebar":"tutorialSidebar"},"camera2/focus":{"id":"camera2/focus","title":"Kapitel 15: Fokus","description":"Meistern Sie sowohl den automatischen als auch den manuellen Fokus in Android Camera2. Verstehen Sie AF-Modi, die AF-Zustandsmaschine, One-Shot-Trigger-and-Capture-Sequenzen, manuellen Fokus mit LENS_FOCUS_DISTANCE in Dioptrien, hyperfokale Distanz und den Aufbau eines Fokus-SeekBar-Schiebereglers in Kotlin.","sidebar":"tutorialSidebar"},"camera2/hdr-and-ultra-hdr":{"id":"camera2/hdr-and-ultra-hdr","title":"Kapitel 21: HDR & Ultra HDR","description":"Implementieren Sie HDR10- und HLG-Video \xfcber DynamicRangeProfiles sowie Android 14 JPEG_R (Ultra HDR ISO 21496-1) Standbildaufnahmen mit einer SDR-Prim\xe4rbild + Gain-Map-Architektur f\xfcr abw\xe4rtskompatible Fotos mit hohem Dynamikumfang.","sidebar":"tutorialSidebar"},"camera2/high-speed-video":{"id":"camera2/high-speed-video","title":"Kapitel 19: High-Speed-Video","description":"Erstellen Sie Zeitlupenaufnahmen mit 120 fps und 240 fps unter Verwendung von CameraConstrainedHighSpeedCaptureSession, createHighSpeedRequestList und den FPS-Bereichen der StreamConfigurationMap in der Android Camera2 API.","sidebar":"tutorialSidebar"},"camera2/manual-exposure-in-camera2":{"id":"camera2/manual-exposure-in-camera2","title":"Kapitel 14: Manuelle Belichtung in Camera2","description":"\xdcbernehmen Sie die volle kreative Kontrolle \xfcber die Belichtung mit der Android Camera2 API. Lernen Sie, die Belichtungsautomatik zu deaktivieren, den manuellen ISO-Wert \xfcber SENSOR_SENSITIVITY einzustellen, die Verschlusszeit in Nanosekunden mit SENSOR_EXPOSURE_TIME zu steuern und bauen Sie funktionierende Kotlin-Beispiele f\xfcr Zeitraffer, Langzeitbelichtungen und Belichtungsreihen.","sidebar":"tutorialSidebar"},"camera2/multi-camera":{"id":"camera2/multi-camera","title":"Kapitel 20: Multi-Kamera","description":"Erforschen Sie logische Multi-Kamera-Ger\xe4te ab Android 9, physische Kamera-IDs, APPROXIMATE vs. CALIBRATED Sensor-Synchronisation, nahtloses Umschalten des Zooms und gleichzeitige Aufnahme \xfcber zwei physische Kameras mittels OutputConfiguration.setPhysicalCameraId() in der Camera2 API.","sidebar":"tutorialSidebar"},"camera2/native-camera-development":{"id":"camera2/native-camera-development","title":"Kapitel 25: Native Kameraentwicklung","description":"Werden Sie nativ mit dem Android NDK Kamera-Stack. Verwenden Sie ACameraManager, um Kameras aus C++ zu \xf6ffnen, binden Sie den AHardwareBuffer-Speicher direkt als Vulkan-Texturen f\xfcr Zero-Copy-AR ein und verstehen Sie die Interoperabilit\xe4t von OpenGL/Vulkan f\xfcr 60-fps-Pipelines. Enth\xe4lt den Kontext der EVS-Migration im Automobilbereich.","sidebar":"tutorialSidebar"},"camera2/opening-a-camera":{"id":"camera2/opening-a-camera","title":"Kapitel 7: Eine Kamera \xf6ffnen","description":"Stellen Sie eine Live-Verbindung zu einem Kamerager\xe4t mit openCamera() her. Beherrschen Sie den CameraDevice-Lebenszyklus, implementieren Sie den StateCallback mit onOpened/onDisconnected/onError, integrieren Sie das \xd6ffnen/Schlie\xdfen mit Activity onPause/onResume und handhaben Sie jeden CameraAccessException-Fehlercode mit Semaphore-basierter Nebenl\xe4ufigkeitssteuerung.","sidebar":"tutorialSidebar"},"camera2/raw-photography":{"id":"camera2/raw-photography","title":"Kapitel 18: RAW-Fotografie","description":"Meistern Sie das RAW_SENSOR-Format, die Erstellung von DNG-Dateien mit DngCreator, Bayer-Muster und die gleichzeitige RAW+JPEG-Aufnahme in der Android Camera2 API.","sidebar":"tutorialSidebar"},"camera2/showing-camera-preview":{"id":"camera2/showing-camera-preview","title":"Kapitel 8: Die Kameravorschau anzeigen","description":"Rendern Sie Live-Kamerabilder auf dem Bildschirm unter Verwendung von TextureView, SurfaceTexture, Surface und CameraCaptureSession. Implementieren Sie den SurfaceTextureListener, korrigieren Sie das Seitenverh\xe4ltnis mit Matrix-Transformationen in configureTransform, erstellen Sie einen TEMPLATE_PREVIEW CaptureRequest und starten Sie den Vorschaustrom mit setRepeatingRequest.","sidebar":"tutorialSidebar"},"camera2/taking-photos":{"id":"camera2/taking-photos","title":"Kapitel 9: Fotos aufnehmen","description":"Nehmen Sie hochwertige Standbilder mit Camera2 unter Verwendung von ImageReader (JPEG), Precapture-AE-Trigger und der CaptureCallback-Zustandsmaschine auf. Speichern Sie Fotos mit dem Scoped-Storage-kompatiblen MediaStore (Android 10+) und dem Legacy-FileOutputStream. Denken Sie immer daran, den Image-Puffer zu schlie\xdfen.","sidebar":"tutorialSidebar"},"camera2/the-camera2-pipeline":{"id":"camera2/the-camera2-pipeline","title":"Kapitel 10: Die Camera2-Pipeline","description":"Tiefer Einblick in die Camera2-Pipeline-Architektur \u2013 CaptureRequest, CaptureResult, Request-Warteschlangen, Ergebnis-Callbacks und der End-to-End-Ablauf von der Einreichung der Anforderung bis zur HAL-Verarbeitung und den Ergebnissen.","sidebar":"tutorialSidebar"},"camera2/understanding-smartphone-cameras":{"id":"camera2/understanding-smartphone-cameras","title":"Kapitel 2: Smartphone-Kameras verstehen","description":"Erkunden Sie die Hardware des Kameramoduls in jedem Smartphone: das Objektiv, den Bildsensor, den ISP-Prozessor, den Unterschied zwischen RAW und JPEG, Multi-Kamera-Designs und den vollst\xe4ndigen Weg von den Photonen zum gespeicherten Foto.","sidebar":"tutorialSidebar"},"camera2/welcome-to-android-camera2":{"id":"camera2/welcome-to-android-camera2","title":"Kapitel 1: Willkommen bei Android Camera2","description":"Erfahren Sie, warum Android Camera2 wichtig ist, wie es sich im Vergleich zu Camera1 und CameraX verh\xe4lt, was es erm\xf6glicht und was Sie in dieser Serie entwickeln werden.","sidebar":"tutorialSidebar"},"camera2/what-can-modern-smartphone-cameras-do":{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen","description":"Ein Rundgang durch die computergest\xfctzten und optischen Funktionen moderner Telefone: HDR, Portr\xe4t-Bokeh, Nachtmodus, Zeitlupe, Ultraweitwinkel, Tele, Makro und wie die computergest\xfctzte Fotografie Hardware und Software verschmilzt.","sidebar":"tutorialSidebar"},"camera2/white-balance-and-color":{"id":"camera2/white-balance-and-color","title":"Kapitel 16: Wei\xdfabgleich & Farbe","description":"Steuern Sie die Farbe in Android Camera2 mit Voreinstellungen f\xfcr den automatischen Wei\xdfabgleich und manueller Farbkorrektur. Lernen Sie AWB-Modi, Farbtemperatur (2000 K \u2013 10000 K), 3\xd73-Farbtransformationen, COLOR_CORRECTION_GAINS und funktionierenden Kotlin-Code f\xfcr warmt\xf6nige Sonnenuntergangs-Voreinstellungen und den voll manuellen Wei\xdfabgleich kennen.","sidebar":"tutorialSidebar"},"camera2/zero-shutter-lag-and-reprocessing":{"id":"camera2/zero-shutter-lag-and-reprocessing","title":"Kapitel 23: Zero Shutter Lag & Reprocessing","description":"Erstellen Sie Zero Shutter Lag (ZSL) mit zirkul\xe4rer YUV/PRIVATE-Pufferung, CONTROL_CAPTURE_INTENT_ZERO_SHUTTER_LAG, reprocessable Aufnahmesitzungen \xfcber InputConfiguration, ImageWriter Frame-Reinjektion und createReprocessCaptureRequest f\xfcr aufwendige ISP-Verarbeitung nach der Aufnahme. Behandelt auch switchToOffline() f\xfcr die Kontinuit\xe4t der Hintergrundverarbeitung.","sidebar":"tutorialSidebar"},"data-safety":{"id":"data-safety","title":"Datensicherheitshandbuch","description":"Datensicherheits- und Datenschutzpraktiken f\xfcr die Android Camera Parameters App. Erfahren Sie mehr \xfcber Kameraberechtigungen und den Umgang mit Hardware-Metadaten.","sidebar":"tutorialSidebar"},"development":{"id":"development","title":"Entwicklerdokumentation","description":"Technische Architektur der Android Camera Parameters App, einschlie\xdflich Details zum MVVM-Muster, Jetpack Compose UI-Struktur und Entwicklungsrichtlinien.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"App-\xdcbersicht","description":"\xdcbersicht \xfcber das Android Camera Parameters Dashboard und seine wichtigsten Diagnosefunktionen, einschlie\xdflich Hardware-Level-Erkennung und Echtzeit-Feature-Tracking.","sidebar":"tutorialSidebar"}}}}')}}]);